  el.style.left=`${hunterRupertState.x}px`;el.style.top=`${hunterRupertState.y}px`;el.style.backgroundPosition=`${-hunterRupertState.frame*20.5}px 0`;el.style.transform=`scaleX(${hunterRupertState.facing<0?-1:1})`;
