  d.returnTrail=planned.length?planned.slice(1):[];
  if(goalWalk&&(!d.returnTrail.length||Math.hypot(d.returnTrail[d.returnTrail.length-1].x-goalWalk.x,d.returnTrail[d.returnTrail.length-1].y-goalWalk.y)>5))d.returnTrail.push({x:goalWalk.x,y:goalWalk.y});
