    if(d.pause<=0){d.waypoint=(d.waypoint+1+Math.floor(Math.random()*2))%HUNTER_DARWIN_WAYPOINTS.length;const p=HUNTER_DARWIN_WAYPOINTS[d.waypoint];d.targetX=p.x;d.targetY=p.y;d.pause=1.2+Math.random()*2.2;}
