function partyPeteItem(id){return PARTY_PETE_WATCHCARDS.find(item=>item.id===id)}
function partyPeteAdminTesting(){return !!(character&&String(character.username||'').toLowerCase()==='catasthma'&&typeof toaState!=='undefined'&&toaState.adminMode)}
function partyPeteOwned(id){return partyPeteAdminTesting()||Number(bankState?.items?.[id]||0)>0}
function partyPeteRefreshTestCard(){
  if(!character?.username)return;
  const key=qmWatcherKey(character.username),existing=qmWatcherProfileCache.get(key)||{};
  qmWatcherProfileCache.set(key,{...existing,username:character.username,equipped_watchcard_background:character.equipped_watchcard_background||null});
  if(qmState?.open&&qmState.liveState)qmRenderWatcherAccounts(qmState.liveState,true);
  if(qmOpenWatcherProfileName&&qmWatcherKey(qmOpenWatcherProfileName)===key)qmRefreshOpenWatcherProfile();
  try{if(typeof renderRepoPassportPanel==='function')renderRepoPassportPanel()}catch(_){}
}
function partyPeteSetTestBackdrop(id){
  character.equipped_watchcard_background=id||null;
  partyPeteRefreshTestCard();
}
function partyPetePreviewMarkup(item){
  const avatar=qmWatcherAvatarForName(character?.username||'');
  return `<div class="party-pete-card-preview" style="--watchcard-bg:url('${item.image}')"><img src="${escapeHtml(avatar)}" alt="Your avatar"><span><small>WATCH PARTY</small><b>${escapeHtml(character?.username||'Your character')}</b></span></div>`;
}
function renderPartyPeteShop(message=partyPeteAdminTesting()?'ADMIN TEST MODE: every background is temporarily unlocked.':'Choose a background to preview it before buying.'){
  const gp=Number(bankState?.gp||0),equipped=character?.equipped_watchcard_background||null;
  const testing=partyPeteAdminTesting();
  $('npcDialogueText').innerHTML=`<section class="party-pete-shop"><header><img src="assets/npc-party-pete.png" alt=""><div><h4>PARTY PETE'S WATCHCARD SHOP</h4><p>${testing?`ADMIN TEST MODE · all ${PARTY_PETE_WATCHCARDS.length} backgrounds unlocked temporarily.`:'World Cup supporter backdrops are 2,000 GP each. Standard backgrounds remain 25,000 GP.'}</p></div><strong>${testing?'TEST UNLOCKS':`${gp.toLocaleString('en-GB')} GP`}</strong></header><div class="party-pete-grid">${PARTY_PETE_WATCHCARDS.map(item=>`<button type="button" class="party-pete-item ${partyPeteOwned(item.id)?'owned':''} ${equipped===item.id?'equipped':''} ${item.id.startsWith('watchcard_wc_')?'world-cup-backdrop':''}" data-watchcard-preview="${item.id}"><img src="${item.image}" alt=""><span><b>${escapeHtml(item.name)}</b><small>${equipped===item.id?'EQUIPPED':testing?'ADMIN TEST · CLICK TO EQUIP':partyPeteOwned(item.id)?'OWNED · CLICK TO EQUIP':formatGpCompact(item.price)}</small></span></button>`).join('')}</div><p class="party-pete-message">${escapeHtml(message)}</p><button class="npc-interface-back" type="button">BACK TO PARTY PETE</button></section>`;
  $('npcDialogueText').querySelectorAll('[data-watchcard-preview]').forEach(button=>button.addEventListener('click',()=>renderPartyPeteConfirmation(button.dataset.watchcardPreview)));
}
function renderPartyPeteConfirmation(id){
  const item=partyPeteItem(id);if(!item)return;const testing=partyPeteAdminTesting(),owned=partyPeteOwned(id),equipped=character?.equipped_watchcard_background===id,afford=Number(bankState?.gp||0)>=item.price;
  $('npcDialogueText').innerHTML=`<section class="party-pete-confirm"><h4>${escapeHtml(item.name)}</h4>${partyPetePreviewMarkup(item)}<p>${testing?(equipped?'This test background is currently equipped.':'Temporarily equip this background for admin testing?'):owned?(equipped?'This background is currently equipped.':'You already own this background. Equip it now?'):`Purchase this background for <b>${item.price.toLocaleString('en-GB')} GP</b>?`}</p><div><button type="button" class="party-pete-confirm-yes" ${!owned&&!afford?'disabled':''}>${equipped?'UNEQUIP':testing?'TEST EQUIP':owned?'EQUIP':afford?'CONFIRM PURCHASE':'NOT ENOUGH GP'}</button><button type="button" class="party-pete-confirm-no">CANCEL</button></div></section>`;
  $('npcDialogueText').querySelector('.party-pete-confirm-no').addEventListener('click',()=>renderPartyPeteShop());
  const yes=$('npcDialogueText').querySelector('.party-pete-confirm-yes');if(!yes.disabled)yes.addEventListener('click',()=>owned?setPartyPeteWatchcard(equipped?null:id):buyPartyPeteWatchcard(id));
}
async function buyPartyPeteWatchcard(id){
  const {data,error}=await db.rpc('buy_watchcard_background',{p_item:id});if(error){console.error(error);renderPartyPeteShop(error.message||'Could not complete purchase. Run add-party-pete-watchcards.sql in Supabase.');return}
  const row=Array.isArray(data)?data[0]:data;
  bankState.gp=Number(row?.new_gp??bankState.gp);
  bankState.items=row?.bank_items||bankState.items;
  character.equipped_watchcard_background=row?.equipped_watchcard_background||id;
  partyPeteRefreshTestCard();
  if($('bankDialog')?.open)renderBank();
  const purchased=partyPeteItem(id);renderPartyPeteShop(`${purchased?.name||'Background'} purchased for ${Number(purchased?.price||0).toLocaleString('en-GB')} GP, added to Account Cosmetics and equipped!`);
}
async function setPartyPeteWatchcard(id,surface='shop'){
  const fromAccount=surface==='account';
  if(partyPeteAdminTesting()){
    partyPeteSetTestBackdrop(id);
    if(fromAccount)renderAccountCosmetics(id?'Background equipped.':'Standard Watchcard restored.');
    else renderPartyPeteShop(id?'Admin test background equipped.':'Admin test background unequipped.');
    return;
  }
  const {data,error}=await db.rpc('set_watchcard_background',{p_item:id});
  if(error){
    console.error(error);
    if(fromAccount)renderAccountCosmetics(error.message||'Could not equip that background.');
    else renderPartyPeteShop(error.message||'Could not equip that background.');
    return;
  }
  const row=Array.isArray(data)?data[0]:data;
  character.equipped_watchcard_background=row?.equipped_watchcard_background||null;
  partyPeteRefreshTestCard();
  if($('bankDialog')?.open)renderBank();
  if($('accountCosmeticsDialog')?.open)renderAccountCosmetics(id?'Background equipped.':'Standard Watchcard restored.');
  if(!fromAccount)renderPartyPeteShop(id?'Background equipped.':'Background unequipped.');
}

function accountOwnedWatchcards(){
  const items=bankState?.items&&typeof bankState.items==='object'?bankState.items:{};
  return PARTY_PETE_WATCHCARDS.filter(item=>Number(items[item.id]||0)>0);
}
function renderAccountCosmetics(message=''){
  const grid=$('accountWatchcardItems');
  if(!grid)return;
  const owned=accountOwnedWatchcards();
  const equippedId=character?.equipped_watchcard_background||null;
  const equipped=partyPeteItem(equippedId);
  $('accountCosmeticsActiveWatchcard').textContent=equipped?.name||'Standard Watchcard';
  $('accountCosmeticsUnequipWatchcard').disabled=!equippedId;
  grid.innerHTML=owned.length?owned.map(item=>{
    const active=equippedId===item.id;
    const type=item.id.startsWith('watchcard_wc_')?'WORLD CUP BACKDROP':'WATCHCARD BACKDROP';
    return `<article class="account-watchcard-item ${active?'equipped':''}">
      <div class="account-watchcard-art"><img src="${item.image}" alt="${escapeHtml(item.name)}"></div>
      <div class="account-watchcard-copy"><b>${escapeHtml(item.name)}</b><small>${type}</small></div>
      <button type="button" data-account-watchcard="${item.id}">${active?'UNEQUIP':'EQUIP'}</button>
    </article>`;
  }).join(''):`<div class="account-cosmetics-empty">No Watchcard backdrops owned yet.<br>Visit Party Pete to purchase one.</div>`;
  grid.querySelectorAll('[data-account-watchcard]').forEach(button=>button.addEventListener('click',()=>{
    const id=button.dataset.accountWatchcard;
    setPartyPeteWatchcard(character?.equipped_watchcard_background===id?null:id,'account');
  }));
  $('accountCosmeticsMessage').textContent=message||`${owned.length} Watchcard backdrop${owned.length===1?'':'s'} owned.`;
}
async function openAccountCosmetics(){
  if(!character){
    toast('Log in or create an account to view cosmetics.');
    openCharacterDialog('login');
    return;
  }
  $('accountCosmeticsDialog').showModal();
  $('accountWatchcardItems').innerHTML='<div class="account-cosmetics-empty">Loading your cosmetics…</div>';
  $('accountCosmeticsMessage').textContent='Checking account unlocks…';
  try{
    await loadBankAndPets();
    const {data,error}=await db.rpc('get_my_watchcard_background');
    if(error)throw error;
    character.equipped_watchcard_background=data?.[0]?.equipped_watchcard_background||null;
    renderAccountCosmetics();
  }catch(error){
    console.error(error);
    $('accountWatchcardItems').innerHTML='<div class="account-cosmetics-empty">Could not load account cosmetics.</div>';
    $('accountCosmeticsMessage').textContent='Could not load Watchcard unlocks.';
  }
}
