  $('toaHetEffects')?.querySelectorAll('.toa-akkha-shadow,.toa-shadow-fire-wave,.toa-akkha-symbol-blast,.toa-akkha-symbol-cue,.toa-unstable-orb,.toa-akkha-projectile,.toa-het-player-projectile').forEach(e=>e.remove());
