// Homepage character shift: six recognisable characters rotate every 1 minute.
(() => {
  const gamer = document.getElementById('gamer');
  const monitor = document.getElementById('characterMonitor');
  if (!gamer || document.getElementById('tavernLobby')) return;
  const variants = [
    { className: 'character-one', monitorClass: 'monitor-toa', monitorLabel: 'Character 1 playing Tombs of Amascut in Old School RuneScape', label: 'Brown-haired character in a brown jumper smoking a hand-rolled joint while playing Tombs of Amascut' },
    { className: 'character-two', monitorClass: 'monitor-stellaris', monitorLabel: 'Character 2 playing Stellaris', label: 'Pale-skinned character in a white outfit with a green cape holding a Dr Pepper while playing Stellaris' },
    { className: 'character-three', monitorClass: 'monitor-isaac', monitorLabel: 'Character 3 playing The Binding of Isaac', label: 'Pale-skinned purple wizard with a blue wizard hat eating quiche while playing The Binding of Isaac' },
    { className: 'character-four', monitorClass: 'monitor-rdr2', monitorLabel: 'Female RuneScape character playing Red Dead Redemption 2', label: 'Female RuneScape adventurer in a silver helm, grey platebody, red trousers and cape holding a Budweiser while playing Red Dead Redemption 2' },
    { className: 'character-five', monitorClass: 'monitor-tlou', monitorLabel: 'Female RuneScape character playing The Last of Us', label: 'Hooded female RuneScape adventurer in cream, green and black armour holding a vape while playing The Last of Us' },
    { className: 'character-six', monitorClass: 'monitor-dti', monitorLabel: 'Female RuneScape character playing Roblox Dress to Impress', label: 'Orange-haired female RuneScape adventurer in a dusty pink blouse and pale green flared trousers holding a pink energy drink while playing Dress to Impress' }
  ];
  const SHIFT_MS = 60000;
  const WALK_MS = 3200;
  let index = 0;
  let timer;
  let changing = false;
  const nextButton = document.getElementById('nextDeskCharacter');

  function applyCharacter(nextIndex) {
    gamer.classList.remove('character-one','character-two','character-three','character-four','character-five','character-six');
    gamer.classList.add(variants[nextIndex].className);
    gamer.setAttribute('aria-label', variants[nextIndex].label);
    if (monitor) {
      monitor.classList.remove('monitor-toa','monitor-stellaris','monitor-isaac','monitor-rdr2','monitor-tlou','monitor-dti');
      monitor.classList.add(variants[nextIndex].monitorClass);
      monitor.setAttribute('aria-label', variants[nextIndex].monitorLabel);
    }
  }

  function scheduleShift() {
    clearTimeout(timer);
    timer = setTimeout(changeShift, SHIFT_MS);
  }

  function changeShift() {
    if (changing) return;
    changing = true;
    if (nextButton) nextButton.disabled = true;
    clearTimeout(timer);
    gamer.classList.remove('typing','entering');
    gamer.classList.add('leaving');
    setTimeout(() => {
      index = (index + 1) % variants.length;
      applyCharacter(index);
      gamer.classList.remove('leaving');
      // Force animation restart after swapping character.
      void gamer.offsetWidth;
      gamer.classList.add('entering');
      setTimeout(() => {
        gamer.classList.remove('entering');
        gamer.classList.add('typing');
        changing = false;
        if (nextButton) nextButton.disabled = false;
        scheduleShift();
      }, WALK_MS);
    }, WALK_MS);
  }

  applyCharacter(index);
  gamer.classList.add('typing');
  scheduleShift();

  if (nextButton) {
    nextButton.addEventListener('click', changeShift);
  }

  document.addEventListener('visibilitychange', () => {
    if (document.hidden) clearTimeout(timer);
    else scheduleShift();
  });
})();

// Homepage environmental scene animation. In billboard mode every transition is a
// true adjacent-frame dissolve: the current sky stays visible while the next sky
// fades over it. This avoids exposing frame 1 between frames and removes the
// dark/light flash that the old tavern-style compositor caused.
(() => {
  const lobby=document.getElementById('tavernLobby');
  if(!lobby)return;
  const baseFrame=lobby.querySelector('.tavern-lobby-base');
  const overlayFrames=[...lobby.querySelectorAll('.tavern-lobby-frame')];
  if(!overlayFrames.length)return;
  const billboardMode=lobby.classList.contains('tavern-lobby--billboard');
  if(!billboardMode){
    const frames=[overlayFrames[0],overlayFrames[1],overlayFrames[2],overlayFrames[3],overlayFrames[5],overlayFrames[6],overlayFrames[8],overlayFrames[6],overlayFrames[5],overlayFrames[3],overlayFrames[2],overlayFrames[1]].filter(Boolean);
    let index=-1,timer=null;
    const showNext=()=>{const previous=frames[index];index=(index+1)%frames.length;previous?.classList.remove('is-visible');frames[index].classList.add('is-visible');};
    const start=()=>{if(timer)return;showNext();timer=setInterval(showNext,260);};
    const stop=()=>{clearInterval(timer);timer=null;};
    start();document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else start();});
    return;
  }

  const source=[baseFrame,...overlayFrames].filter(Boolean);
  // Move forward through the wind/cloud sequence and then back through it so
  // the loop boundary is 2 -> 1 rather than a sudden 8 -> 1 lighting jump.
  const order=[0,1,2,3,4,5,6,7,6,5,4,3,2,1];
  const dissolveMs=1120;
  const holdMs=1320;
  let orderIndex=0,timer=null,current=source[order[0]];

  source.forEach((img,i)=>{
    img.classList.remove('is-visible');
    img.style.transition=`opacity ${dissolveMs}ms cubic-bezier(.22,.61,.36,1)`;
    img.style.opacity=i===order[0]?'1':'0';
    img.style.zIndex=i===order[0]?'2':'1';
    img.style.willChange='opacity';
  });

  const advance=()=>{
    const nextOrder=(orderIndex+1)%order.length;
    const next=source[order[nextOrder]];
    if(!next||next===current){orderIndex=nextOrder;return;}
    const previous=current;
    next.style.transition='none';
    next.style.opacity='0';
    next.style.zIndex='3';
    previous.style.zIndex='2';
    void next.offsetWidth;
    next.style.transition=`opacity ${dissolveMs}ms cubic-bezier(.22,.61,.36,1)`;
    next.style.opacity='1';
    window.setTimeout(()=>{
      if(previous!==next){previous.style.transition='none';previous.style.opacity='0';previous.style.zIndex='1';}
      next.style.zIndex='2';
      current=next;
      orderIndex=nextOrder;
    },dissolveMs+35);
  };
  const start=()=>{if(timer)return;timer=setInterval(advance,holdMs);};
  const stop=()=>{clearInterval(timer);timer=null;};
  start();
  document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else start();});
})();


// Billboard World Cup advertisements: hold each fixture for eleven seconds,
// then dissolve directly into the next. This layer is independent of the
// wind/cloud environmental animation so neither transition can flash through
// the other.
(() => {
  const layer=document.getElementById('billboardAdLayer');
  if(!layer)return;
  const slides=[...layer.querySelectorAll('.billboard-ad-slide')];
  if(slides.length<2)return;
  slides.forEach(slide=>{
    const img=slide.querySelector('img');
    if(img){const preload=new Image();preload.src=img.src;}
  });
  let index=0,timer=null;
  const advance=()=>{
    const previous=slides[index];
    index=(index+1)%slides.length;
    const next=slides[index];
    next.classList.add('is-active');
    window.setTimeout(()=>previous.classList.remove('is-active'),1480);
  };
  const start=()=>{if(timer)return;timer=window.setInterval(advance,11000);};
  const stop=()=>{if(timer){window.clearInterval(timer);timer=null;}};
  start();
  document.addEventListener('visibilitychange',()=>{
    if(document.hidden)stop();
    else start();
  });
})();

// Tavern ambience is deliberately opt-in. Browsers never hear it until they
// press the small speaker control, and it is kept at a room-tone volume.
(() => {
  const toggle=document.getElementById('tavernSoundToggle');
  if(!toggle)return;
  const ambience=new Audio('assets/tavern-ambience.mp3');
  ambience.loop=true;ambience.preload='metadata';ambience.volume=.15;
  let playing=false;
  const render=()=>{
    toggle.setAttribute('aria-pressed',String(playing));
    toggle.setAttribute('aria-label',playing?'Mute tavern ambience':'Unmute tavern ambience');
    toggle.title=playing?'Mute tavern ambience':'Unmute tavern ambience';
    toggle.querySelector('span').textContent=playing?'🔊':'🔇';
  };
  toggle.addEventListener('click',async()=>{
    if(playing){ambience.pause();playing=false;render();return;}
    try{ambience.volume=.15;await ambience.play();playing=true;}catch(_){playing=false;}
    render();
  });
  window.addEventListener('pagehide',()=>{ambience.pause();});
  render();
})();

