function playRepoCombatSound(baseAudio, volume) {
  try {
    const audio = baseAudio.cloneNode();
    audio.volume = volume;
    audio.currentTime = 0;
    const promise = audio.play();
    if (promise?.catch) promise.catch(() => {});
  } catch (_) {}
}
function playRepoCombatWaveSound() { playRepoCombatSound(repoCombatWaveSound, .60); }
function playRepoCombatHealOrbSound() { playRepoCombatSound(repoCombatHealOrbSound, .50); }
function playRepoCombatXpOrbSound() { playRepoCombatSound(repoCombatXpOrbSound, .25); }
let repoRareDropRollBusy=false;
function showRepoPurpleDropNotice(){
  let notice=document.getElementById('repoPurpleDropNotice');
  if(!notice){notice=document.createElement('div');notice.id='repoPurpleDropNotice';notice.innerHTML='<span>◆</span><b>You have received a purple drop!</b>';document.body.appendChild(notice);}
  notice.classList.remove('show');void notice.offsetWidth;notice.classList.add('show');
  clearTimeout(notice._hideTimer);notice._hideTimer=setTimeout(()=>notice.classList.remove('show'),1100);
}
async function tryRepoCombatRareDrop(){
  if(repoRareDropRollBusy||!character)return;repoRareDropRollBusy=true;
  try{
    const {data,error}=await db.rpc('roll_repo_combat_rare_drop');
    if(error){if(!/roll_repo_combat_rare_drop|schema cache|could not find/i.test(`${error.message||''} ${error.details||''}`))console.warn('Rare-drop roll failed:',error);return;}
    const row=Array.isArray(data)?data[0]:data;if(!row?.won)return;
    if(bankState){bankState.items=bankState.items||{};bankState.items.repo_combat_rare_drop=Number(row.quantity||Number(bankState.items.repo_combat_rare_drop||0)+1);if($('bankDialog')?.open)renderBank();}
    showRepoPurpleDropNotice();
  }catch(error){console.warn('Rare-drop roll failed:',error)}finally{repoRareDropRollBusy=false}
}
